/* SkylineGlass: city wallpaper, live settings, readable lyrics and fullscreen clock. */
const SKYLINE_DEFAULT_WALLPAPER = "data:image/jpeg;base64,";
(function(){const style=document.createElement("style");style.id="skylineglass-base";style.textContent="/* Fixed desktop wallpaper; keep LiquidMusic glass panels. */\nhtml body #lm-backdrop {\n background: var(--sg-wallpaper) center center / cover no-repeat !important;\n}\nhtml body #lm-backdrop .lm-backdrop-layer { display: none !important; }\nhtml:root[data-liquidmusic-mode=\"dark\"], html:root {\n --lm-bg-content: rgba(22, 22, 24, 0.62) !important;\n --lm-glass-thick-bg: rgba(30, 30, 32, 0.55) !important;\n}\n\n\n/* Put the fullscreen wallpaper on the stationary view, outside its scroll viewport. */\nhtml[data-cinema-npv-postEnter] .main-actionBar-ActionBarContainer {\n background: linear-gradient(rgba(0,0,0,var(--sg-darkness, .55)), rgba(0,0,0,var(--sg-darkness, .55))), var(--sg-wallpaper) center / cover no-repeat !important;\n}\nhtml[data-cinema-npv-postEnter] [style*=\"--cinema-mode-bg-color-from\"] {\n --cinema-mode-bg-color-from: transparent !important;\n --cinema-mode-bg-color-to: transparent !important;\n background: transparent !important;\n}\nhtml[data-cinema-npv-postEnter] [style*=\"--cinema-mode-bg-color-from\"] > :empty {\n background: none !important;\n box-shadow: none !important;\n}\n\n/* Lyrics readability: upcoming lines remain legible over the wallpaper. */\nhtml body [style*=\"--lyrics-color-background\"] {\n --lyrics-color-active: #fff !important;\n --lyrics-color-inactive: rgba(255,255,255,var(--sg-lyrics, .70)) !important;\n --lyrics-color-passed: rgba(255,255,255,.50) !important;\n --lyrics-color-messaging: rgba(255,255,255,var(--sg-lyrics, .70)) !important;\n text-shadow: 0 2px 5px rgba(0,0,0,.85) !important;\n}\nhtml body #lm-backdrop::after { background: rgba(0,0,0,var(--sg-darkness, .55)) !important; }\n\n/* Hide the collapsed right-side Now Playing pull-out tab. */\nbutton[aria-label=\"Show Now Playing view\"] { display: none !important; }\n\n/* Keep the queue available without the collapsed sidebar surface. */\nhtml:not(:has([data-testid=\"control-button-queue\"]:is([aria-checked=\"true\"], [aria-pressed=\"true\"]), button[aria-label=\"Queue\"]:is([aria-checked=\"true\"], [aria-pressed=\"true\"]))) .Root__top-container > :has(button[aria-label=\"Show Now Playing view\"]) {\n display: none !important;\n}\n";document.documentElement.appendChild(style);})();
(function skylineGlassSettings() {
  const KEY = 'skylineglass.settings.v1';
  const defaults = {darkness:55, blur:0, lyrics:70, clock:true, hour12:true, accentMode:'album', accent:'#fa2d48'};
  let prefs = {...defaults};
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || '{}');
    for (const k of ['darkness','blur','lyrics']) if (Number.isFinite(saved[k])) prefs[k] = Math.max(0,Math.min(k==='blur'?40:100,saved[k]));
    for (const k of ['clock','hour12']) if (typeof saved[k]==='boolean') prefs[k]=saved[k];
    if (saved.accentMode === 'fixed') prefs.accentMode='fixed';
    if (/^#[0-9a-f]{6}$/i.test(saved.accent)) prefs.accent=saved.accent;
  } catch (_) {}
  window.SkylineGlassSettings = prefs;
  let wallpaper = SKYLINE_DEFAULT_WALLPAPER;
  const runtimeStyle = document.createElement('style');
  runtimeStyle.id = 'skylineglass-preferences';
  document.documentElement.appendChild(runtimeStyle);
  let host, shadow, dialog, status, preview;
  let wallpaperRevision=0;
  let renderedWallpaper;
  let renderVersion=0;
  let displayedWallpaper=SKYLINE_DEFAULT_WALLPAPER;
  const wallpaperStyle=document.createElement('style');
  wallpaperStyle.id='skylineglass-wallpaper-image';
  document.documentElement.appendChild(wallpaperStyle);
  function paintWallpaper(uri) {
    displayedWallpaper=uri;
    const background=`linear-gradient(rgba(0,0,0,var(--sg-darkness,.55)),rgba(0,0,0,var(--sg-darkness,.55))),url("${uri}") center / cover no-repeat`;
    wallpaperStyle.textContent=`html body #lm-backdrop {background:url("${uri}") center / cover no-repeat!important;} html[data-cinema-npv-postEnter] .main-actionBar-ActionBarContainer {background:${background}!important;}`;
    // Update the existing surface directly as well as future surfaces matched by the stylesheet.
    const scene=document.querySelector('.main-actionBar-ActionBarContainer');
    if(scene)scene.style.setProperty('background',background,'important');
    const backdrop=document.getElementById('lm-backdrop');
    if(backdrop)backdrop.style.setProperty('background',`url("${uri}") center / cover no-repeat`,'important');
  }
  function dbAction(mode, action) {
    return new Promise((resolve,reject) => {
      const request=indexedDB.open('SkylineGlass',1);
      request.onupgradeneeded=()=>request.result.createObjectStore('assets');
      request.onerror=()=>reject(request.error);
      request.onsuccess=()=>{
        const db=request.result, tx=db.transaction('assets',mode);
        let result;
        try { const req=action(tx.objectStore('assets')); req.onsuccess=()=>{result=req.result;}; }
        catch(e) {db.close();reject(e);return;}
        tx.oncomplete=()=>{db.close();resolve(result);};
        tx.onerror=()=>{db.close();reject(tx.error);};
        tx.onabort=()=>{db.close();reject(tx.error);};
      };
    });
  }
  function message(text) { if(status) status.textContent=text; }
  function apply(save=true) {
    const accent = prefs.accentMode==='fixed' ? `
      --lm-accent:${prefs.accent}!important;
      --spice-button:${prefs.accent}!important;
      --spice-button-active:${prefs.accent}!important;
      --spice-text-bright-accent:${prefs.accent}!important;
      --lm-on-accent:${parseInt(prefs.accent.slice(1,3),16)*.299+parseInt(prefs.accent.slice(3,5),16)*.587+parseInt(prefs.accent.slice(5,7),16)*.114>155?'#000':'#fff'}!important;` : '';
    const renderKey=wallpaper+':'+prefs.blur;
    if(renderedWallpaper!==renderKey) {
      renderedWallpaper=renderKey;
      const version=++renderVersion;
      const source=wallpaper, blur=prefs.blur;
      const root=document.documentElement;
      paintWallpaper(source);
      if(blur>0) {
        const image=new Image();
        image.onload=()=>{
          if(version!==renderVersion)return;
          const scale=Math.min(1,1600/image.naturalWidth);
          const canvas=document.createElement('canvas');
          canvas.width=Math.round(image.naturalWidth*scale);
          canvas.height=Math.round(image.naturalHeight*scale);
          const ctx=canvas.getContext('2d');
          const bleed=Math.ceil(blur*scale*3);
          ctx.filter=`blur(${blur*scale}px)`;
          ctx.drawImage(image,-bleed,-bleed,canvas.width+bleed*2,canvas.height+bleed*2);
          if(version===renderVersion)paintWallpaper(canvas.toDataURL('image/jpeg',.9));
        };
        image.src=source;
      }
    } else {paintWallpaper(displayedWallpaper);}
    runtimeStyle.textContent=`html:root {
      --sg-darkness:${prefs.darkness/100}; --sg-lyrics:${prefs.lyrics/100}; ${accent}
    }
`;
    if(preview) preview.style.backgroundImage=`linear-gradient(rgba(0,0,0,${prefs.darkness/100}),rgba(0,0,0,${prefs.darkness/100})),url("${wallpaper}")`;
    if(save) {try {localStorage.setItem(KEY,JSON.stringify(prefs));message('Saved · changes are live');} catch(_) {message('Applied for this session. Settings storage is unavailable.');}}
    window.dispatchEvent(new Event('skylineglass-settings-change'));
  }
  const CSS=`
  :host{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display",sans-serif;color:#f8f9fc;color-scheme:dark;font-size:14px}
  *{box-sizing:border-box}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #a8caff;outline-offset:4px}
  #launcher{position:fixed;right:20px;bottom:24px;z-index:1000;display:flex;align-items:center;gap:0;border:1px solid #ffffff25;border-radius:50%;width:38px;height:38px;justify-content:center;padding:0;background:#20232bd9;backdrop-filter:blur(22px);color:#fff;box-shadow:0 4px 20px #0005;font-size:12px;font-weight:500;letter-spacing:.01em}
  #launcher:hover{background:#353a46}#launcher svg{width:16px;height:16px}
  dialog{position:fixed;margin:auto;padding:0;width:460px;max-width:calc(100vw - 32px);max-height:calc(100vh - 48px);overflow:auto;border:1px solid #ffffff24;border-radius:24px;background:#17191ff2;color:#f8f9fc;box-shadow:0 24px 100px #0009;backdrop-filter:blur(32px)}
  dialog::backdrop{background:#0008;backdrop-filter:blur(8px)}
  header{display:flex;justify-content:space-between;align-items:flex-start;padding:26px 26px 20px}h1{font-size:27px;font-weight:500;letter-spacing:-1px;margin:0 0 5px}.subtitle{color:#b7bdcb;font-size:12px;margin:0}
  .close{border:0;border-radius:50%;background:#ffffff12;color:#dce0e9;width:30px;height:30px;font-size:22px;line-height:1}
  main{padding:0 26px}.preview{height:105px;border:1px solid #ffffff15;border-radius:14px;background-size:cover;background-position:center;display:flex;align-items:end;padding:12px;margin-bottom:12px;color:#fff;text-shadow:0 2px 5px #000}
  .preview span{font-size:10px;letter-spacing:.12em;font-weight:600}
  section{padding:20px 0;border-top:1px solid #ffffff12}h2{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#9da9bd;font-weight:600;margin:0 0 15px}
  .row{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:13px 0}.row:last-child{margin-bottom:0}.row:first-of-type{margin-top:0}.value{color:#aab6c9;font-variant-numeric:tabular-nums;font-size:12px}
  .range{display:grid;grid-template-columns:1fr 43px;gap:16px;align-items:center;margin:8px 0 16px}.range:last-child{margin-bottom:0}input[type=range]{width:100%;accent-color:#a5c7ff;height:4px}input[type=checkbox]{accent-color:#a5c7ff;width:32px;height:18px;cursor:pointer}input[type=color]{width:42px;height:29px;border:0;border-radius:6px;padding:2px;background:#ffffff12}
  select{padding:7px 26px 7px 10px;border:1px solid #ffffff20;border-radius:8px;background:#252a34;color:#eef2fa;font-size:12px}.buttons{display:flex;gap:8px}.secondary{border:1px solid #ffffff20;background:#ffffff08;border-radius:9px;padding:8px 12px;color:#e2e8f4;font-size:12px}.secondary:hover{background:#ffffff15}.hint{color:#969fae;font-size:11px;line-height:1.5;margin:8px 0 0}
  footer{border-top:1px solid #ffffff12;padding:16px 26px 22px;display:flex;align-items:center;justify-content:space-between;gap:12px}#status{color:#a6b4c8;font-size:11px;max-width:240px}.reset{color:#c5cedd;border:0;background:none;font-size:11px;text-decoration:underline;text-underline-offset:3px}input[type=file]{display:none}
  @media(prefers-reduced-motion:no-preference){dialog[open]{animation:appear .18s ease-out}@keyframes appear{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}}
  `;
  function init() {
    if(!document.body) {setTimeout(init,100);return;}
    host=document.createElement('div');host.id='skylineglass-settings';
    shadow=host.attachShadow({mode:'open'});
    shadow.innerHTML=`<style>${CSS}</style>
    <button id="launcher" aria-label="SkylineGlass settings" title="SkylineGlass settings"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M9.5 3h5l.6 2.5 2 .9 2.3-.7 2.5 4.3-1.8 1.8v2.4l1.8 1.8-2.5 4.3-2.3-.7-2 .9-.6 2.5h-5l-.6-2.5-2-.9-2.3.7L2.1 16l1.8-1.8v-2.4L2.1 10l2.5-4.3 2.3.7 2-.9L9.5 3Z" transform="translate(0 -1) scale(1 .96)"/><circle cx="12" cy="12" r="3.2"/></svg></button>
    <dialog aria-labelledby="sg-title"><header><div><h1 id="sg-title">SkylineGlass</h1><p class="subtitle">Make the city your own.</p></div><button class="close" aria-label="Close settings">×</button></header>
    <main><div class="preview"><span>YOUR BACKDROP</span></div>
    <div class="buttons"><button id="choose" class="secondary">Choose wallpaper</button><button id="original" class="secondary">Use city wallpaper</button><input id="file" type="file" accept="image/jpeg,image/png,image/webp"></div><p class="hint">JPG, PNG or WebP · up to 10 MB · Spotify refreshes after selection</p>
    <section><h2>Atmosphere</h2><label for="darkness">Wallpaper darkness</label><div class="range"><input id="darkness" type="range" min="0" max="90"><output for="darkness" id="darkness-value" class="value"></output></div>
    <label for="blur">Background blur</label><div class="range"><input id="blur" type="range" min="0" max="40"><output for="blur" id="blur-value" class="value"></output></div>
    <div class="row"><label for="accentMode">Accent color</label><select id="accentMode"><option value="album">Follow album</option><option value="fixed">Fixed color</option></select><input id="accent" type="color" aria-label="Choose fixed accent color"></div></section>
    <section><h2>Lyrics</h2><label for="lyrics">Upcoming lyric brightness</label><div class="range"><input id="lyrics" type="range" min="30" max="100"><output for="lyrics" id="lyrics-value" class="value"></output></div></section>
    <section><h2>Clock</h2><div class="row"><label for="clock">Show fullscreen clock</label><input id="clock" type="checkbox"></div><div class="row"><label for="hour12">Time format</label><select id="hour12"><option value="true">12 hour</option><option value="false">24 hour</option></select></div></section></main>
    <footer><span id="status" role="status">Changes apply instantly</span><button class="reset" id="reset">Reset settings</button></footer></dialog>`;
    dialog=shadow.querySelector('dialog');status=shadow.querySelector('#status');preview=shadow.querySelector('.preview');
    function sync() {
      for(const k of ['darkness','blur','lyrics']) {shadow.getElementById(k).value=prefs[k];shadow.getElementById(k+'-value').textContent=prefs[k]+(k==='blur'?' px':'%');}
      shadow.getElementById('clock').checked=prefs.clock;
      shadow.getElementById('hour12').value=String(prefs.hour12);
      shadow.getElementById('accentMode').value=prefs.accentMode;
      shadow.getElementById('accent').value=prefs.accent;
      shadow.getElementById('accent').hidden=prefs.accentMode!=='fixed';
    }
    shadow.getElementById('launcher').onclick=()=>{sync();dialog.showModal();};
    shadow.querySelector('.close').onclick=()=>dialog.close();
    // Keep Spotify's playback shortcuts from firing while editing a control.
    dialog.addEventListener('keydown',e=>e.stopPropagation());
    dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
    for(const k of ['darkness','blur','lyrics','clock','hour12','accentMode','accent']) {
      shadow.getElementById(k).addEventListener('input',e=>{
        prefs[k]=['darkness','blur','lyrics'].includes(k)?Number(e.target.value):k==='clock'?e.target.checked:k==='hour12'?e.target.value==='true':e.target.value;
        sync();apply();
      });
    }
    let file=shadow.getElementById('file');
    async function chooseImage(event) {
      const input=event.currentTarget;
      const image=input.files && input.files[0];
      // Clear immediately so selecting the same filename again also fires change.
      input.value='';
      if(!image)return;
      const supported=/^image\/(jpeg|png|webp)$/i.test(image.type) || (!image.type && /\.(jpe?g|png|webp)$/i.test(image.name));
      if(!supported || image.size>10*1024*1024){message('Choose a JPG, PNG or WebP under 10 MB.');return;}
      const revision=++wallpaperRevision;message('Loading wallpaper…');
      let uri;
      try {
        uri=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(image);});
        const decoded=new Image();decoded.src=uri;await decoded.decode();
        if(revision!==wallpaperRevision)return;
        // Apply before writing to storage; a slow save must not block the visible change.
        wallpaper=uri;apply(false);message('Wallpaper applied · saving…');
      } catch(error) {message('This image could not be opened. Try exporting it as JPG or PNG.');return;}
      try {
        await dbAction('readwrite',store=>store.put(uri,'wallpaper'));
        if(revision===wallpaperRevision){message('Wallpaper saved · refreshing Spotify…');setTimeout(()=>window.location.reload(),150);}
      } catch(error) {
        if(revision===wallpaperRevision)message('Wallpaper applied for this session, but could not be saved.');
      }
    }
    shadow.getElementById('choose').onclick=()=>{
      // Chromium can retain state on a reused file input after a native picker closes.
      const fresh=file.cloneNode(false);
      file.replaceWith(fresh);file=fresh;
      file.addEventListener('change',chooseImage);
      file.click();
    };
    async function restoreImage(reset=false) {
      ++wallpaperRevision;
      try {await dbAction('readwrite',store=>store.delete('wallpaper'));wallpaper=SKYLINE_DEFAULT_WALLPAPER;if(reset)Object.assign(prefs,defaults);sync();apply();message('Wallpaper saved · refreshing Spotify…');setTimeout(()=>window.location.reload(),150);}
      catch(_){message('Could not reset saved wallpaper. Please try again.');}
    }
    shadow.getElementById('original').onclick=()=>restoreImage();
    shadow.getElementById('reset').onclick=()=>restoreImage(true);
    const mount=()=>{const parent=document.fullscreenElement||document.body;if(host.parentElement!==parent)parent.appendChild(host);};
    mount();document.addEventListener('fullscreenchange',mount);
    let currentScene;
    setInterval(()=>{mount();const next=document.querySelector('.main-actionBar-ActionBarContainer');if(next!==currentScene){currentScene=next;apply(false);}},1000);
    sync();apply(false);
    const revision=wallpaperRevision;
    dbAction('readonly',store=>store.get('wallpaper')).then(uri=>{if(revision===wallpaperRevision&&typeof uri==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(uri)){wallpaper=uri;apply(false);}}).catch(()=>message('Custom wallpaper storage is unavailable.'));
  }
  init();
})();

/* SkylineGlass fullscreen clock, centered in the fullscreen top toolbar row. */
(function skylineGlassClock() {
  if (window.__skylineGlassClockCleanup) window.__skylineGlassClockCleanup();
  const clock = document.createElement('time');
  clock.id = 'skylineglass-clock';
  clock.setAttribute('aria-label', 'Current time');
  Object.assign(clock.style, {
    position: 'fixed', display: 'none', pointerEvents: 'none', zIndex: '100',
    transform: 'translateX(-50%)', color: '#fff', whiteSpace: 'nowrap',
    fontFamily: '-apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", sans-serif',
    fontSize: 'clamp(18px, 1.5vw, 24px)', fontWeight: '300',
    fontVariantNumeric: 'tabular-nums', letterSpacing: '-.035em',
    lineHeight: '1.2', textShadow: '0 2px 8px rgba(0,0,0,.85)'
  });
  let formatter = new Intl.DateTimeFormat(undefined, {
    hour: 'numeric', minute: '2-digit', hour12: true
  });
  let currentHour12=true;
  function update() {
    const prefs=window.SkylineGlassSettings || {clock:true,hour12:true};
    if (!prefs.clock) {clock.style.display='none';return;}
    if (prefs.hour12!==currentHour12) {
      currentHour12=prefs.hour12;
      formatter=new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit',hour12:currentHour12});
    }
    // Cinema includes the expanded song view and real fullscreen; ordinary pages have no clock.
    const cinema = document.documentElement.hasAttribute('data-cinema-npv-postEnter');
    const scene = cinema && document.querySelector('[style*="--cinema-mode-bg-color-from"]');
    if (!scene || scene.querySelector('[style*="--lyrics-color-background"]')) {
      clock.style.display = 'none';
      return;
    }
    const images = Array.from(scene.querySelectorAll('img')).map(image => ({
      image, rect: image.getBoundingClientRect()
    })).filter(({image, rect}) => rect.width > 120 && rect.height > 120 &&
      rect.top >= 0 && rect.top < innerHeight && rect.bottom > 0 &&
      rect.left < innerWidth && rect.right > 0 && getComputedStyle(image).visibility !== 'hidden');
    images.sort((a, b) => b.rect.width * b.rect.height - a.rect.width * a.rect.height);
    if (!images.length) { clock.style.display = 'none'; return; }
    const rect = images[0].rect;
    const host = document.fullscreenElement || document.body;
    if (clock.parentElement !== host) host.appendChild(clock);
    const now = new Date();
    const label = formatter.format(now);
    if (clock.textContent !== label) {
      clock.textContent = label;
      clock.dateTime = now.toISOString();
      clock.setAttribute('aria-label', 'Current time: ' + label);
    }
    clock.style.left = '50%';
    clock.style.display = 'block';
    const nav = document.querySelector('.Root__globalNav');
    const navBottom = !document.fullscreenElement && nav ? nav.getBoundingClientRect().bottom : 0;
    clock.style.top = `${Math.max(0, navBottom) + 42 - clock.offsetHeight / 2}px`;
  }
  const timer = setInterval(update, 1000);
  window.addEventListener('resize', update);
  window.addEventListener('skylineglass-settings-change', update);
  document.addEventListener('fullscreenchange', update);
  document.addEventListener('scroll', update, true);
  window.__skylineGlassClockCleanup = () => {
    clearInterval(timer);
    window.removeEventListener('resize', update);
    window.removeEventListener('skylineglass-settings-change', update);
    document.removeEventListener('fullscreenchange', update);
    document.removeEventListener('scroll', update, true);
    clock.remove();
  };
  update();
})();
